      padding: 1.25rem 1.5rem;
      max-width: 680px; width: calc(100% - 3rem);
      display: flex; align-items: center; gap: 1.5rem;
      flex-wrap: wrap;
      z-index: 2000;
      box-shadow: 0 20px 60px rgba(0,0,0,0.6);
      transition: opacity 0.3s, transform 0.3s;
    }
