      opacity: 0; pointer-events: none;
      transform: translateX(-50%) translateY(20px);
    }
    .cookie-text {
      flex: 1; min-width: 200px;
      font-size: 0.85rem; color: var(--text-secondary);
      line-height: 1.55;
